// One-time helper: downloads the Latin subset of the three UI fonts from Google Fonts into vendor/fonts/
// and writes vendor/fonts/fonts.css with relative URLs. build.py inlines them, so the app needs no network.
//   node vendor/fetch-fonts.js
// Fonts: Bricolage Grotesque, Plus Jakarta Sans, JetBrains Mono — SIL Open Font License 1.1.
const https = require('https'); const fs = require('fs'); const path = require('path');
const CSS_URL = 'https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700;12..96,800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500&display=swap';
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36';
const OUT = path.join(__dirname, 'fonts');
const get = url => new Promise((res, rej) => https.get(url, { headers: { 'User-Agent': UA } }, r => { if (r.statusCode !== 200) return rej(new Error(r.statusCode + ' ' + url)); const c = []; r.on('data', d => c.push(d)); r.on('end', () => res(Buffer.concat(c))); }).on('error', rej));
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const css = (await get(CSS_URL)).toString();
  // keep only the "latin" blocks (the UI text is English)
  const blocks = [...css.matchAll(/\/\* ([\w-]+) \*\/\s*(@font-face\s*\{[^}]*\})/g)].filter(m => m[1] === 'latin').map(m => m[2]);
  const files = {}; let outCss = '/* Latin subsets from Google Fonts (SIL Open Font License 1.1). Generated by fetch-fonts.js. */\n';
  for (const b of blocks) {
    const url = b.match(/url\((https:[^)]+)\)/)[1]; const fam = b.match(/font-family: '([^']+)'/)[1].replace(/\s+/g, '');
    const name = files[url] || (files[url] = fam + '-' + Object.keys(files).length + '.woff2');
    if (!fs.existsSync(path.join(OUT, name))) fs.writeFileSync(path.join(OUT, name), await get(url));
    outCss += b.replace(url, name).replace(/\n\s*/g, ' ') + '\n';
  }
  fs.writeFileSync(path.join(OUT, 'fonts.css'), outCss);
  console.log(blocks.length + ' @font-face rules, ' + new Set(Object.values(files)).size + ' files:', fs.readdirSync(OUT).map(f => f + ' ' + fs.statSync(path.join(OUT, f)).size).join(', '));
})().catch(e => { console.error(e.message); process.exit(1); });
